export type DisplayFamilyField = FamilyField & {
  text: string; requirement: string; kind: "text" | "picker" | "interests";
  choices: { id: string; text: string }[];
};

/** Render the saved text verbatim, with the same language fallback on both clients. */
export function displayFamilyForm(form: FamilyFormConfig, locale: "zh" | "en") {
  const text = (value: FamilyText) => value[locale] || value.zh;
  const fields: DisplayFamilyField[] = form.fields.filter(field => field.mode !== "hidden").map(field => ({
    ...field, text: text(field.label),
    requirement: field.mode === "required" ? (locale === "zh" ? "（必填）" : " (required)") : (locale === "zh" ? "（选填）" : " (optional)"),
    kind: field.id === "interests" ? "interests" : ["relation", "gender", "grade"].includes(field.id) ? "picker" : "text",
    choices: (field.options || []).map(option => ({ id: option.id, text: text(option.label) })),
  }));
  return { title: text(form.title), description: text(form.description), fields };
}

export function onboardingChoices(locale: "zh" | "en"): Record<string, string[]> {
  const words = onboardingCopy[locale];
  return {
    relation: [locale === "zh" ? "请选择" : "Choose", ...words.relations],
    gender: words.genders,
    grade: locale === "zh" ? [words.chooseGrade, "幼中班", "幼大班", "一年级", "二年级", "三年级", "四年级", "五年级", "六年级", "初一", "初二", "初三", "高一", "高二", "高三"]
      : [words.chooseGrade, "K2", "K3", ...Array.from({ length: 12 }, (_, index) => `Grade ${index + 1}`)],
  };
}
